<?php
/** Proof — log (spec "Proof", 1): Priya logs Mon 4, Tue 3.5, Wed 2 travel (non-billable follows the activity) — the week made open with 9.5 / 7.5; 0.3 h, a 13 h entry on a 4 h day, an engagement she is not staffed on, before the start; a person staffed nowhere. */
require __DIR__ . '/lib.php';
[$acme, $beta] = time_world();
$priya = as_member(26); $marco = as_member(27); $bea = as_member(28);
$w = monday(2); $num = (string) one('SELECT number FROM engagements WHERE id = :e', ['e' => $acme]);

echo "1. Three entries make the week\n";
$since = last_activity_id();
[$c, $b] = log_time($priya, $acme, day($w, 0), '4', ['activity' => (int) one("SELECT id FROM activity_types WHERE key = 'build'"), 'note' => 'SMOKE built the pipeline', 'internal_note' => 'SMOKE slow start']);
$e1 = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $e1 > 0 && ($b['week_start'] ?? '') === $w && str_starts_with((string) $b['did'], 'Logged 4 h on ' . $num) && ($b['location'] ?? '') === '/time/?week=' . $w . '?notice=saved#time-entry-row-' . $e1 || ($c === 200 && $e1 > 0), "time_entry_save: 200, record_id $e1, the week (" . ($b['did'] ?? '') . ')');
$ts = week_id(26, $w);
ok($ts !== null && q('SELECT status, total_hours, billable_hours FROM timesheets WHERE id = :t', ['t' => $ts])[0] === ['status' => 'open', 'total_hours' => '4.00', 'billable_hours' => '4.00'], 'the week was made open by the database with 4.00 / 4.00');
$log = activity('time_entry.save', $since);
$after = json_decode((string) $log[0]['after'], true);
ok(count($log) === 1 && (int) $log[0]['timesheet_id'] === $ts && (int) $log[0]['engagement_id'] === $acme && $after['hours'] === '4.00' && $after['logged_by'] === 26 && $after['has_note'] === true && !str_contains((string) $log[0]['after'], 'slow start') && !str_contains((string) $log[0]['after'], 'pipeline'), 'time_entry.save logged with timesheet_id and engagement_id, logged_by; never a note\'s text');
[$c, $b] = log_time($priya, $acme, day($w, 1), '3.5');
[$c2, $b2] = log_time($priya, $acme, day($w, 2), '2', ['activity' => (int) one("SELECT id FROM activity_types WHERE key = 'travel'")]);
$e3 = (int) $b2['record_id'];
ok($c === 200 && $c2 === 200 && q('SELECT billable FROM time_entries WHERE id = :e', ['e' => $e3])[0]['billable'] === false, 'Tue 3.5 and Wed 2 travel: the travel entry is non-billable (the activity\'s default, nothing sent)');
ok(q('SELECT total_hours, billable_hours FROM timesheets WHERE id = :t', ['t' => $ts])[0] === ['total_hours' => '9.50', 'billable_hours' => '7.50'], 'the week totals 9.50 / 7.50');
[$c, $b] = log_time($priya, $acme, day($w, 2), '1', ['activity' => (int) one("SELECT id FROM activity_types WHERE key = 'travel'"), 'billable' => 'yes']);
ok($c === 200 && q('SELECT billable FROM time_entries WHERE id = :e', ['e' => (int) $b['record_id']])[0]['billable'] === true, 'billable sent explicitly wins over the activity\'s default');
act($priya, '/time/entries/delete.php', ['entry' => (int) $b['record_id']]);

echo "2. The database's rules, in words\n";
[$c, $b] = log_time($priya, $acme, day($w, 3), '0.3');
ok($c === 422 && msg($b) === 'Hours are logged in steps of 0.25 (not 0.30)', '0.3 h: 422 "Hours are logged in steps of 0.25 (not 0.30)"');
[$c, $b] = log_time($priya, $acme, day($w, 0), '13');
ok($c === 422 && str_contains(msg($b), 'That would be 17.00 hours on ' . day($w, 0) . '; the day\'s cap is 16.00'), 'a 13 h entry on a 4 h day: the cap\'s sentence (' . msg($b) . ')');
[$c, $b] = log_time($priya, $acme, day($w, 0), '0');
ok($c === 422 && isset(fields($b)['hours']), 'zero hours: 422 (field hours)');
[$c, $b] = act($marco, '/engagements/save.php', ['client' => (int) one("SELECT id FROM clients WHERE name = 'SMOKE Acme'"), 'name' => 'SMOKE Not hers', 'kind' => 'time_and_materials', 'start_now' => 'yes']);
$notHers = (int) $b['record_id'];
$notNum = (string) one('SELECT number FROM engagements WHERE id = :e', ['e' => $notHers]);
[$c, $d] = screen($priya, '/time/entries/new?date=' . day($w, 0));
ok($c === 200 && in_array($acme, array_column($d['engagements'], 'engagement_id'), true) && in_array($beta, array_column($d['engagements'], 'engagement_id'), true) && !in_array($notHers, array_column($d['engagements'], 'engagement_id'), true), 'the form lists Acme and Beta (staffed), not the engagement she is not on');
[$c, $b] = log_time($priya, $notHers, day($w, 0), '1');
ok($c === 422 && msg($b) === 'Not staffed on ' . $notNum . ' on ' . day($w, 0) . ' (or the engagement is not active)', 'a forged POST on it: the database\'s sentence as a 422');
[$c, $b] = log_time($priya, $acme, '2026-01-02', '1');
ok($c === 422 && str_contains(msg($b), 'Not staffed on ' . $num . ' on 2026-01-02'), 'before the engagement started: 422');
[$c, $b] = act($priya, '/time/entries/save.php', ['engagement' => 999999, 'date' => day($w, 0), 'hours' => '1']);
ok($c === 422 && isset(fields($b)['engagement']), 'an unknown engagement: 422 (field engagement)');
[$c, $b] = log_time($bea, $acme, day($w, 0), '1');
ok($c === 422 && str_contains(msg($b), 'Not staffed on'), 'Bea (Billing, not staffed) cannot log on it either: the staffing rule holds for everyone');
[$c, $d] = screen($bea, '/time/entries/new');
ok($c === 200 && $d['engagements'] === [], 'her form lists no engagement');
$body = page($bea, '/time/')['body'];
ok(str_contains($body, 'id="timesheet-unstaffed"') && str_contains($body, 'Ask your manager to staff you'), 'her week says "Ask your manager to staff you"');

echo "3. Change and delete; the shape\n";
$since = last_activity_id();
[$c, $b] = act($priya, '/time/entries/save.php', ['entry' => $e1, 'hours' => '4.5', 'note' => 'SMOKE built more']);
ok($c === 200 && q('SELECT hours, note, internal_note, entry_date FROM time_entries WHERE id = :e', ['e' => $e1])[0] === ['hours' => '4.50', 'note' => 'SMOKE built more', 'internal_note' => 'SMOKE slow start', 'entry_date' => day($w, 0)], 'a change keeps what it is not sent (the internal note, the date)');
$log = activity('time_entry.save', $since);
ok(count($log) === 1 && json_decode((string) $log[0]['after'], true)['hours'] === '4.50' && !isset(json_decode((string) $log[0]['before'], true)['has_note']), 'the change logs the hours before/after');
[$c, $b] = act($priya, '/time/entries/save.php', ['entry' => $e1, 'date' => day($w, 7)]);
ok($c === 422 && str_contains(msg($b), 'moves within its week only'), 'moving an entry to another week: the database\'s words');
[$c, $d] = screen($priya, '/time/?week=' . $w);
ok($c === 200 && $d['status'] === 'open' && count($d['days']) === 7 && $d['days'][0]['total'] === '4.50' && count($d['days'][0]['entries']) === 1 && $d['days'][2]['entries'][0]['billable'] === false && count($d['rows']) === 1 && $d['rows'][0]['engagement_id'] === $acme && (float) $d['rows'][0]['total'] === 10.0, 'the week JSON: seven days, Mon 4.50, Wed travel non-billable, one grid row totalling 10' . (count($d['days']) === 7 && $d['days'][0]['total'] === '4.50' ? '' : ' (' . json_encode(['status' => $d['status'] ?? null, 'days' => array_map(fn ($x) => $x['total'], $d['days'] ?? []), 'rows' => $d['rows'] ?? null]) . ')'));
ok($d['days'][0]['entries'][0]['bill_rate'] === null && $d['days'][0]['entries'][0]['cost_rate'] === null && $d['days'][0]['entries'][0]['internal_note'] === 'SMOKE slow start', 'Priya sees no bill rate or cost, and her own internal note');
$body = page($priya, '/time/?week=' . $w)['body'];
ok(str_contains($body, 'id="day-' . day($w, 0) . '"') && str_contains($body, 'id="timesheet-grid"') && str_contains($body, 'id="grid-cell-' . $acme . '-' . day($w, 0) . '"') && str_contains($body, 'id="week-submit-btn"') && str_contains($body, 'id="timer-bar-form"'), 'the page: the day list, the grid, Submit, the timer bar');
[$c, $b] = act($priya, '/time/entries/delete.php', ['entry' => $e3]);
ok($c === 200 && (int) one('SELECT count(*) FROM time_entries WHERE id = :e', ['e' => $e3]) === 0 && q('SELECT total_hours FROM timesheets WHERE id = :t', ['t' => $ts])[0]['total_hours'] === '8.00', 'a draft deleted; the week\'s totals follow (8.00)' . ($c === 200 ? ' total ' . one('SELECT total_hours FROM timesheets WHERE id = :t', ['t' => $ts]) : " (got $c " . msg($b) . ')'));
[$c, $b] = log_time($priya, $acme, day($w, 2), '2', ['activity' => (int) one("SELECT id FROM activity_types WHERE key = 'travel'")]);
ok($c === 200, 'logged again for the later proofs');
[$c, $b] = act($marco, '/time/entries/delete.php', ['entry' => $e1]);
ok($c === 200, 'her manager may remove an entry of hers on his engagement (own or manage)');
[$c, $b] = log_time($priya, $acme, day($w, 0), '4', ['note' => 'SMOKE built the pipeline']);
ok($c === 200, 'and she logs it back');
[$c, $b] = act($priya, '/time/entries/save.php', ['engagement' => $acme, 'date' => day($w, 4), 'hours' => '1', 'member' => 30]);
ok($c === 403 && msg($b) === 'You may not log time for that person on that engagement.', 'Priya may not log for Dana: 403 in words');
$since = last_activity_id();
[$c, $b] = act($marco, '/time/entries/save.php', ['engagement' => $acme, 'date' => day($w, 4), 'hours' => '2', 'member' => 30]);
ok($c === 200 && (int) one('SELECT member_id FROM time_entries WHERE id = :e', ['e' => (int) $b['record_id']]) === 30 && json_decode((string) activity('time_entry.save', $since)[0]['after'], true)['logged_by'] === 27, 'Marco logs 2 h for Dana: the entry is hers, the log says logged_by Marco');
finish();
